#include <stdio.h>
int main(void) {
    int n = 1000;
    int a = 600, b = 300, c = 100;   /* 三类指令条数 */
    int ca = 1, cb = 2, cc = 4;      /* 各类 CPI */
    long cycles = (long)a * ca + (long)b * cb + (long)c * cc;
    double cpi = (double)cycles / n;
    printf("指令总数 = 1000\n");
    printf("  A类(60%%) CPI=1: %d 条 -> %ld 周期\n", a, (long)a * ca);
    printf("  B类(30%%) CPI=2: %d 条 -> %ld 周期\n", b, (long)b * cb);
    printf("  C类(10%%) CPI=4: %d 条 -> %ld 周期\n", c, (long)c * cc);
    printf("总时钟周期 = %ld\n", cycles);
    printf("平均CPI = %ld / %d = %.2f\n", cycles, n, cpi);
    return 0;
}
